  "bibCards.collapseAll": "Tout replier",
  "bibCards.expandAll": "Tout déplier",
  "bibCards.addEntry": "＋ entrée",
  "bibCards.addEntryTitle": "Ajouter une nouvelle entrée @misc à la fin du fichier",
  "bibCards.noEntries": "Ce fichier ne contient encore aucune entrée bibliographique.",
  "bibCards.noMatches": "Aucune entrée ne correspond à « {query} ».",
  "bibCards.strayOne": "1 ligne hors de toute entrée (un commentaire ou du texte libre) n'est pas affichée ici — voir la Source.",
  "bibCards.strayMany": "{n} lignes hors de toute entrée (commentaires ou texte libre) ne sont pas affichées ici — voir la Source.",
  "bibCards.foldTitle": "Replier cette entrée",
  "bibCards.expandTitle": "Déplier cette entrée",
  "bibCards.typeLabel": "Type d'entrée",
  "bibCards.typeTitle": "Type d'entrée (article, inproceedings, …)",
  "bibCards.keyLabel": "Clé de citation",
  "bibCards.keyTitle": "Clé de citation — ce que \\cite{…} désigne",
  "bibCards.duplicateBadge": "clé en double",
  "bibCards.duplicateTitle": "Une autre entrée de ce fichier utilise la même clé de citation — la bibliographie n'en gardera qu'une.",
